+        ctx.lineWidth = Math.max(1, bw * .002);
+        ctx.stroke();
+        ctx.fillStyle = 'rgba(99,48,18,.7)';
+        [[-.22,-.18],[.17,-.25],[.28,.12],[-.12,.24]].forEach(p => {
+          ellipsePath(p[0] * size, p[1] * size, size * .025, size * .025);
