+        });
+        ctx.restore();
+      }
+
+      function drawMushroom(x, y, size, rotation, bw) {
+        ctx.save();
+        ctx.translate(x, y);
+        ctx.rotate(rotation);
+        ctx.scale(1, .52);
+        let g = ctx.createRadialGradient(-size * .18, -size * .2, 0, 0, 0, size * .6);
+        g.addColorStop(0, '#b47a47');
+        g.addColorStop(.45, '#754527');
+        g.addColorStop(1, '#29170f');
+        ctx.fillStyle = g;
+        ellipsePath(0, 0, size * .5, size * .5);
