+      function setPointer(e) {
+        const rect = canvas.getBoundingClientRect();
+        pointer.tx = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
+        pointer.ty = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));
+        pointer.active = true;
+
+        const m = bowlMetrics();
+        const nx = (e.clientX - m.cx) / (m.bw * .475);
+        const ny = (e.clientY - m.cy) / (m.bh * .205);
+        if (nx * nx + ny * ny < 1 && (!ripples.length || performance.now() * .001 - ripples[ripples.length - 1].born > .16)) {
+          ripples.push({ x: nx, y: ny, born: performance.now() * .001 });
+        }
+        if (reduceMotion.matches) render(performance.now() * .001, true);
+      }
+
+      canvas.addEventListener('pointermove', setPointer, { passive: true });
+      canvas.addEventListener('pointerdown', setPointer, { passive: true });
+      canvas.addEventListener('pointerleave', () => {
+        pointer.tx = .5;
+        pointer.ty = .45;
+        pointer.active = false;
+        if (reduceMotion.matches) render(performance.now() * .001, true);
+      });
+      addEventListener('resize', resize, { passive: true });
+      reduceMotion.addEventListener?.('change', restart);
+
+      resize();
+      restart();
+    })();
+  </script>
+</body>
+</html>

